window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[195]={"id":"195","numero":195,"titre":"Horton, PPR & Takayasu","objectifs":[{"id":"195-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’artérite à cellules géantes (ACG)","contenu":"<p><span class=\"kw-def\">Vascularite granulomateuse</span> des vaisseaux de <span class=\"kw-def\">gros calibre</span>, survenant chez le sujet de <span class=\"kw-chiffre\">> 50 ans</span> (pic de fréquence <span class=\"kw-chiffre\">70–80 ans</span>).</p>\n      <p>Territoires préférentiellement atteints :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Aorte</span> et ses gros troncs ;</li>\n        <li>Vaisseaux à destinée <span class=\"kw-clinique\">céphalique</span> : branches de l'<span class=\"kw-clinique\">artère carotide externe</span> (artères temporales++), carotide interne, <span class=\"kw-clinique\">artères vertébrales</span> ;</li>\n        <li>Vaisseaux des <span class=\"kw-clinique\">membres supérieurs</span> : <span class=\"kw-clinique\">artères sous-clavières</span>, axillaires.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> L'ACG (« maladie de Horton ») et la <span class=\"kw-def\">PPR</span> sont considérées par la majorité des auteurs comme deux expressions cliniques distinctes d'une <span class=\"kw-def\">même maladie</span> : elles peuvent se succéder, être intriquées (<span class=\"kw-chiffre\">15 %</span> des cas), et partagent les mêmes facteurs immunogénétiques (HLA-DR4, hyperproduction d'<span class=\"kw-bio\">IL-6</span>).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique</em></p>","frequence":0},{"id":"195-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la pseudo-polyarthrite rhizomélique (PPR)","contenu":"<p><span class=\"kw-def\">Rhumatisme inflammatoire</span> bilatéral et symétrique des <span class=\"kw-clinique\">ceintures scapulaire et pelvienne</span> (« rhizomélique » = racine des membres).</p>\n      <p>Caractéristiques fondamentales :</p>\n      <ul>\n        <li><strong>Pas une <span class=\"kw-def\">vascularite</span></strong> ❌ : aucune atteinte d'autres appareils que l'<span class=\"kw-clinique\">appareil locomoteur</span> ;</li>\n        <li>Sujet de <span class=\"kw-chiffre\">> 50 ans</span>, prédominance féminine (<span class=\"kw-chiffre\">2F/1H</span>), pic <span class=\"kw-chiffre\">70–80 ans</span> ;</li>\n        <li><span class=\"kw-clinique\">Arthro-myalgies</span> à <span class=\"kw-clinique\">horaire inflammatoire</span> (raideur matinale <span class=\"kw-chiffre\">> 60 min</span>) évoluant depuis <span class=\"kw-chiffre\">> 1 mois</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">\n        <strong>Lien ACG ↔ PPR.</strong> Dans la <span class=\"kw-chiffre\">majorité des cas (85 %)</span>, ACG et PPR surviennent <span class=\"kw-clinique\">isolément</span>. Quand elles sont associées (<span class=\"kw-chiffre\">15 %</span>), elles peuvent être simultanées ou successives :\n        <ul style=\"margin-top:6px;\">\n          <li><span class=\"kw-chiffre\">40–60 %</span> des patients ACG ont des symptômes de PPR ;</li>\n          <li><span class=\"kw-chiffre\">20 %</span> des patients PPR ont une ACG associée.</li>\n        </ul>\n        <strong>Tout tableau compatible avec une PPR doit donc faire rechercher cliniquement une ACG associée.</strong>\n      </div>","frequence":0},{"id":"195-3","rang":"B","rubrique":"Prévalence","titre":"Connaître les principales caractéristiques épidémiologiques de l’ACG et la PPR","contenu":"<p>Données épidémiologiques comparatives (ACG <span class=\"kw-bio\">vs</span> PPR) — à retenir pour le « profil-type » EDN.</p>\n      <table >\n        <thead>\n          <tr><th>Paramètre</th><th>ACG (Horton)</th><th>PPR</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Prévalence</td>\n            <td><span class=\"kw-chiffre\">1/1000</span></td>\n            <td><span class=\"kw-chiffre\">6/1000</span><br><em>3 à 10× plus fréquente que l'ACG</em></td>\n          </tr>\n          <tr>\n            <td>Incidence</td>\n            <td colspan=\"2\"><span class=\"kw-clinique\">Augmente avec l'âge</span> (ACG : <span class=\"kw-chiffre\">1/10 000</span> personnes de <span class=\"kw-chiffre\">> 50 ans</span> / an)</td>\n          </tr>\n          <tr>\n            <td>Âge</td>\n            <td colspan=\"2\">Survient après <span class=\"kw-chiffre\">> 50 ans</span> avec un <span class=\"kw-clinique\">pic de fréquence entre 70 et 80 ans</span></td>\n          </tr>\n          <tr>\n            <td>Sex-ratio</td>\n            <td colspan=\"2\">Prédominance <span class=\"kw-clinique\">féminine</span> :<br><strong>Rhumato :</strong> <span class=\"kw-chiffre\">2F/1H</span> ;<br><strong>Médecine interne :</strong> <span class=\"kw-chiffre\">4F/1H</span></td>\n          </tr>\n          <tr>\n            <td>Géographie</td>\n            <td colspan=\"2\">Gradient décroissant <span class=\"kw-clinique\">Nord → Sud</span> de l'Europe (plus fréquent au Nord)</td>\n          </tr>\n          <tr>\n            <td>Ethnies</td>\n            <td colspan=\"2\">Moins touchées : <span class=\"kw-clinique\">Asiatiques</span> et <span class=\"kw-clinique\">Africains</span></td>\n          </tr>\n          <tr>\n            <td>Association<br>ACG ↔ PPR</td>\n            <td colspan=\"2\">\n              <strong>Isolées :</strong> <span class=\"kw-chiffre\">85 %</span> ;<br>\n              <strong>Associées :</strong> <span class=\"kw-chiffre\">15 %</span> (simultanées ou successives) ;<br>\n              <strong>ACG → sx de PPR :</strong> <span class=\"kw-chiffre\">40–60 %</span> ;<br>\n              <strong>PPR → ACG associée :</strong> <span class=\"kw-chiffre\">20 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Pronostic</td>\n            <td colspan=\"2\">Globalement <span class=\"kw-clinique\">bon</span>, survie globale = population générale (<strong>pas de surmortalité démontrée</strong>) ; rechutes possibles parfois <span class=\"kw-chiffre\">jusqu'à 10 ans</span> après</td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"195-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","contenu":"<p>Manifestations cliniques <span class=\"kw-clinique\">polymorphes</span>, isolées ou associées : <strong>aucune n'est constante</strong>. La triade EDN à intégrer : <em>âge <span class=\"kw-chiffre\">> 50 ans</span> + symptômes évocateurs + <span class=\"kw-def\">syndrome inflammatoire</span> biologique</em> → suspecter ACG.</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Signes cliniques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Signes généraux</td>\n            <td><span class=\"kw-clinique\">Fièvre :</span> dépasse rarement <span class=\"kw-chiffre\">39 °C</span> ;<br><span class=\"kw-clinique\">Asthénie :</span> fréquente ;<br><span class=\"kw-clinique\">Anorexie + amaigrissement :</span> <span class=\"kw-clinique\">AEG</span> habituellement plus marquée que dans la PPR isolée</td>\n          </tr>\n          <tr>\n            <td>Céphaliques<br>(symptômes vasculaires crâniens)</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Céphalée</span> temporale :</strong> uni ou bilatérale, récente, intensité variable, <span class=\"kw-clinique\">résistante au paracétamol</span> ;<br>\n              <strong>Hyperesthésie du cuir chevelu :</strong> douleur au coiffage = <span class=\"kw-clinique\">signe du peigne</span> (risque évolutif rare : <span class=\"kw-alerte\">nécrose du scalp</span>) ;<br>\n              <strong>Claudication intermittente langue/mâchoire :</strong> contracture des <span class=\"kw-clinique\">masséters</span> à la mastication, cédant à l'arrêt (risque rare : <span class=\"kw-alerte\">nécroses linguales</span>) ;<br>\n              <strong>Palpation des artères temporales :</strong> induration, sensibilité, saillie, abolition/diminution du pouls temporal (palper des 2 côtés, en avant du tragus)\n            </td>\n          </tr>\n          <tr>\n            <td>Rhumatologiques</td>\n            <td>Symptômes de <span class=\"kw-clinique\">PPR associée</span> : <span class=\"kw-chiffre\">50 %</span> selon le collège de médecine interne, <span class=\"kw-chiffre\">15 %</span> selon le collège de rhumato</td>\n          </tr>\n          <tr>\n            <td>Ophtalmologiques<br>(<span class=\"kw-chiffre\">~30 %</span>)</td>\n            <td>\n              <span class=\"kw-alerte\">BAV unilatérale :</span> indolore, brutale (<span class=\"kw-chiffre\">15 %</span> des patients) ;<br>\n              <span class=\"kw-alerte\">Amaurose brutale :</span> perte de vision transitoire de quelques secondes à minutes ;<br>\n              <span class=\"kw-alerte\">Flou visuel, scotome, diplopie transitoire</span> (paralysie oculomotrice)<br>\n              <em>(Détail des étiologies et complications dans l'objectif « Identifier une urgence ».)</em>\n            </td>\n          </tr>\n          <tr>\n            <td>Drapeaux rouges 🚩<br>(<em>contre</em> ACG/PPR)</td>\n            <td>\n              <span class=\"kw-alerte\">Organomégalie :</span> <span class=\"kw-clinique\">adénopathies</span>, splénomégalie, hépatomégalie ;<br>\n              <span class=\"kw-alerte\">Atteinte des petits vaisseaux :</span> <span class=\"kw-def\">purpura</span> vasculaire, <span class=\"kw-def\">syndrome néphritique</span>/néphrotique, mononeuropathie multiple, polynévrite (évoque <span class=\"kw-bio\">ANCA</span>…) ;<br>\n              <span class=\"kw-alerte\">Absence de réponse clinique</span> après quelques jours de <span class=\"kw-ttt\">corticothérapie</span> ;<br>\n              <span class=\"kw-alerte\">Absence de syndrome inflammatoire biologique</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":4},{"id":"195-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels de l’ACG","contenu":"<p>Dans la <strong>forme typique</strong>, il n'y a quasiment pas de DD. Ils émergent surtout dans les <span class=\"kw-clinique\">formes frustes</span>.</p>\n      <table >\n        <thead>\n          <tr><th>Catégorie de DD</th><th>Pathologies à évoquer / élimination</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Autres causes de SIB prolongé<br><em>(éliminer par BAT ou imagerie vasculaire)</em></td>\n            <td>\n              <strong>Infections :</strong> syphilis (aortite), <span class=\"kw-def\">tuberculose</span>, salmonellose ;<br>\n              <strong>Néoplasies ;</strong><br>\n              <strong>MTEV ;</strong><br>\n              <strong>Autres pathologies inflammatoires :</strong> Takayasu, Wegener, périartérite noueuse, Behçet\n            </td>\n          </tr>\n          <tr>\n            <td>NOIAA <span class=\"kw-clinique\">inaugurale, isolée</span></td>\n            <td>DD principal = <span class=\"kw-clinique\">athérosclérose</span> (cause la plus fréquente de NOIAA)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Endocardite</span> infectieuse subaiguë</td>\n            <td><strong>DD majeur</strong> : donne aussi <span class=\"kw-clinique\">fièvre</span> + SIB + manifestations rhumatologiques ± <span class=\"kw-def\">AVC</span></td>\n          </tr>\n          <tr>\n            <td>Autres causes de <span class=\"kw-clinique\">céphalée</span></td>\n            <td>Mais si <em><span class=\"kw-clinique\">céphalée</span> + SIB + âge <span class=\"kw-chiffre\">> 50 ans</span></em> → évoquer <span class=\"kw-clinique\">systématiquement</span> l'ACG</td>\n          </tr>\n          <tr>\n            <td>Maladies de surcharge / IgG4</td>\n            <td>Maladie d'<span class=\"kw-clinique\">Erdheim-Chester</span>, certaines maladies associées aux IgG4</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique · 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":0},{"id":"195-6","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les complications ophtalmologiques de l’ACG : amaurose brutale, paralysie oculomotrice","contenu":"<div class=\"callout callout-warn\">\n        <strong>Urgence thérapeutique absolue.</strong> Les complications ophtalmologiques de l'ACG sont la <span class=\"kw-alerte\">principale complication ischémique</span> (<span class=\"kw-chiffre\">5 à 30 %</span> des patients). Tout signe ophtalmo chez un patient suspect d'ACG impose une <span class=\"kw-ttt\">corticothérapie en urgence</span> pour prévenir la <span class=\"kw-alerte\">cécité bilatérale définitive</span>.\n      </div>\n      <table >\n        <thead>\n          <tr><th></th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Signes d'alerte</td>\n            <td>\n              <strong>BAV unilatérale :</strong> <span class=\"kw-clinique\">indolore</span> le plus souvent, <span class=\"kw-clinique\">brutale</span>, peut survenir chez <span class=\"kw-chiffre\">15 %</span> des patients ;<br>\n              <strong>Amaurose brutale :</strong> perte de vision <span class=\"kw-clinique\">transitoire</span> de quelques secondes à minutes, complète ou simple amputation du champ visuel ;<br>\n              <strong>Flou visuel, scotome, diplopie transitoire</strong> (paralysie oculomotrice)\n            </td>\n          </tr>\n          <tr>\n            <td>Étiologies ⚠️</td>\n            <td>\n              <strong>NOIAA :</strong> <span class=\"kw-clinique\">neuropathie optique ischémique antérieure aiguë</span> par <span class=\"kw-alerte\">nécrose</span> = <em>principale</em> ;<br>\n              <strong>OACR :</strong> occlusion de l'artère centrale de la rétine (<span class=\"kw-chiffre\">2 %</span> des maladies de Horton) ;<br>\n              <strong>NOIPA :</strong> neuropathie optique <span class=\"kw-etio\">ischémique</span> postérieure (très rare et débattue)\n            </td>\n          </tr>\n          <tr>\n            <td>Risque évolutif</td>\n            <td>\n              <strong>Atteinte unilatérale :</strong> risque important d'<span class=\"kw-alerte\">atteinte controlatérale</span> et de <span class=\"kw-alerte\">cécité totale définitive</span> (justifie CTC en urgence) ;<br>\n              <strong>Cécité irréversible :</strong> <span class=\"kw-chiffre\">10 à 15 %</span> des cas (<span class=\"kw-chiffre\">1–2 %</span> bilatérale,<span class=\"kw-chiffre\"> 5 %</span> unilatérale selon le collège)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Autres complications ischémiques de l'ACG</strong> à connaître par territoire :</p>\n      <table >\n        <thead>\n          <tr><th>Territoire</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Vertébrales / carotides</td>\n            <td><span class=\"kw-alerte\">AVC ischémique, AIT</span> (<span class=\"kw-chiffre\">5–7 %</span>)</td>\n          </tr>\n          <tr>\n            <td>Gerbe aortique</td>\n            <td>Syndrome de l'<span class=\"kw-clinique\">arc aortique</span> avec acrocyanose distale, Raynaud, <span class=\"kw-def\">IDM</span> ostial coronaire (2/3 des cas)</td>\n          </tr>\n          <tr>\n            <td>Aorte</td>\n            <td><span class=\"kw-alerte\">Dissection aortique, anévrysme, insuffisance aortique</span>, dilatation diffuse</td>\n          </tr>\n          <tr>\n            <td>Artères des membres</td>\n            <td>Claudication intermittente, <span class=\"kw-clinique\">asymétrie tensionnelle</span>, abolition de pouls, souffle vasculaire</td>\n          </tr>\n          <tr>\n            <td>Autres territoires</td>\n            <td>\n              <strong>Pulmonaire :</strong> <span class=\"kw-clinique\">toux</span> chronique, infiltrat ;<br>\n              <strong>Rénal :</strong> <span class=\"kw-alerte\">HTA</span> ;<br>\n              <strong>Digestif :</strong> <span class=\"kw-alerte\">infarctus mésentérique</span> ;<br>\n              <strong>Nerfs oculomoteurs :</strong> diplopie (<span class=\"kw-chiffre\">2 %</span>) ;<br>\n              <strong>Neuropsychiatrique (<span class=\"kw-chiffre\">3 %</span>) :</strong> <span class=\"kw-clinique\">désorientation</span>, troubles de l'humeur (corticosensibles)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 81 — Altération chronique de la vision · 340 — <span class=\"kw-def\">AVC</span> · 224 — <span class=\"kw-def\">HTA</span></em></p>","frequence":0},{"id":"195-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les signes biologiques fréquents au cours de l’ACG","contenu":"<p>Le bilan biologique cherche surtout à <strong>objectiver un <span class=\"kw-def\">syndrome inflammatoire</span> biologique</strong> et à éliminer les drapeaux rouges qui orienteraient vers une <span class=\"kw-def\">vascularite</span> des petits vaisseaux.</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Résultats attendus / commentaires</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Syndrome inflammatoire</span> biologique (SIB)</td>\n            <td>\n              <strong>Sensibilité :</strong> <span class=\"kw-clinique\">quasi-constant</span> (<span class=\"kw-chiffre\">> 95 %</span>) — son absence rend le diagnostic d'ACG/PPR <em>très improbable</em> ;<br>\n              <strong>Définition :</strong> élévation de 2 protéines de l'inflammation (<span class=\"kw-bio\">CRP + fibrinogène</span>) OU élévation de la <span class=\"kw-bio\">VS + CRP</span> ;<br>\n              <strong>Intensité :</strong> très marqué la plupart du temps (<span class=\"kw-bio\">CRP > 40 mg/L</span>, voire <span class=\"kw-bio\">VS > 40 mm/h</span>) ; parfois plus modéré\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-bio\">Hémogramme</span></td>\n            <td><span class=\"kw-bio\">Anémie inflammatoire</span> ; <span class=\"kw-bio\">thrombocytose</span> d'origine inflammatoire</td>\n          </tr>\n          <tr>\n            <td>Bilan hépatique</td>\n            <td>\n              Perturbation dans <span class=\"kw-chiffre\">20–30 %</span> des cas :<br>\n              <strong>Cholestase anictérique :</strong> <span class=\"kw-bio\">γGT + PAL élevées</span>, <span class=\"kw-bio\">bilirubine normale</span> ;<br>\n              <strong>Cytolyse :</strong> parfois (2N à 5N)\n            </td>\n          </tr>\n          <tr>\n            <td>Auto-anticorps</td>\n            <td>\n              <span class=\"kw-ci\">Aucun auto-Ac spécifique</span> de la PPR ou de l'ACG ❌. Leur présence éventuelle (FR, <span class=\"kw-bio\">AAN</span>…) est une <em>coïncidence liée à l'âge</em> du patient — peu d'importance diagnostique.\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":1},{"id":"195-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires utiles pour confirmer le diagnostic","contenu":"<div class=\"callout callout-info\">\n        <strong>2 moyens pour confirmer une ACG :</strong>\n        <ol>\n          <li><span class=\"kw-imagerie\">Écho-doppler des axes vasculaires</span> = examen de <strong>1ʳᵉ intention</strong> si suspicion d'ACG ;</li>\n          <li><span class=\"kw-imagerie\">Biopsie de l'artère temporale (BAT)</span> = examen de <strong>référence</strong>, mais <em>non indispensable</em> si diagnostic posé par l'imagerie.</li>\n        </ol>\n        Du fait des progrès de l'imagerie, le diagnostic <span class=\"kw-imagerie\">histologique</span> est de moins en moins nécessaire.\n      </div>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indication / résultats</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\">Écho-<span class=\"kw-imagerie\">doppler</span></span><br>des axes vasculaires</td>\n            <td>\n              <strong>Axes explorés :</strong> artères <span class=\"kw-imagerie\">temporales</span> + gros vaisseaux du cou et TSAO (carotides, axillaires) ;<br>\n              <strong>Signes d'artérite</strong> (opérateur entraîné, à distinguer de l'athérosclérose) :<br>\n              <span class=\"kw-radio\">Signe du halo</span> (halo hypoéchogène circonférentiel) — <span class=\"kw-chiffre\">Sp 100 % si bilatéral</span>, permet de se passer de la preuve histologique si tableau clinico-bio compatible ;<br>\n              Signes de <span class=\"kw-imagerie\">thrombose</span> ou de <span class=\"kw-imagerie\">sténose</span> artérielle ; <span class=\"kw-imagerie\">incompressibilité</span> de l'artère\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TEP-TDM</span></td>\n            <td>\n              Examen de <strong>référence</strong> pour l'ACG <span class=\"kw-clinique\">extra-crâniale</span> :<br>\n              <strong>Zones inflammatoires :</strong> <span class=\"kw-radio\">fixation intense</span> des parois vasculaires ;<br>\n              <strong>Coupes scanographiques associées :</strong> visualisent plus précisément l'atteinte aortique\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Angio-IRM / Angio-TDM</span></td>\n            <td>\n              Visualisation des atteintes des <span class=\"kw-clinique\">vaisseaux intracrâniens</span> non accessibles au <span class=\"kw-imagerie\">TEP-TDM</span> ;<br>\n              <strong>Signe typique :</strong> <span class=\"kw-radio\">épaississement circonférentiel et homogène</span> de la paroi vasculaire\n            </td>\n          </tr>\n          <tr>\n            <td>BAT — <span class=\"kw-clinique\">réalisation</span></td>\n            <td>\n              <strong>Anesthésie :</strong> locale ;<br>\n              <strong>Taille du prélèvement :</strong> <span class=\"kw-chiffre\">> 0,5–1 cm de long</span> (<span class=\"kw-chiffre\">1 cm</span> selon collège de Rhumato) ;<br>\n              <strong>Préparation :</strong> fixation dans le <span class=\"kw-ttt\">formol</span> (sinon risque accru de faux négatif) ;<br>\n              <strong>Côté :</strong> segment long, du côté <span class=\"kw-clinique\">le plus symptomatique</span> ; si négatif → biopsier l'autre côté\n            </td>\n          </tr>\n          <tr>\n            <td>BAT — <span class=\"kw-clinique\">initiation traitement</span></td>\n            <td>\n              La BAT ne doit <strong>pas retarder</strong> l'initiation du traitement si la suspicion est forte :<br>\n              Sensibilité de la BAT diminue seulement après <span class=\"kw-chiffre\">2 semaines</span> de traitement ;<br>\n              Lésions histologiques peuvent persister <span class=\"kw-chiffre\">plusieurs mois</span>\n            </td>\n          </tr>\n          <tr>\n            <td>BAT — <span class=\"kw-clinique\">sensibilité</span></td>\n            <td>\n              <span class=\"kw-bio\">50–90 %</span>. Normale dans <span class=\"kw-chiffre\">1/3 des cas</span> (atteinte temporale segmentaire et focale → on peut prélever un fragment d'artère normal). <strong>Une BAT négative n'élimine PAS le diagnostic.</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>BAT — <span class=\"kw-clinique\">histologie</span></td>\n            <td>\n              <strong>Panartérite :</strong> infiltrat de cellules <span class=\"kw-bio\">mononucléées</span> (<span class=\"kw-bio\">lymphocytes</span>, macrophages) dans les <span class=\"kw-chiffre\">3 tuniques</span> ;<br>\n              <strong>Cellules géantes mononucléées :</strong> caractéristique mais inconstantes ;<br>\n              <strong>Fragmentation de la limitante élastique interne</strong> (sépare adventice/média) ;<br>\n              <strong>Hyperplasie intimale</strong> → sténose voire occlusion vasculaire ;<br>\n              <span class=\"kw-ci\">PAS de nécrose fibrinoïde</span> ❌ (point négatif important)\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":4},{"id":"195-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de l’ACG et son pronostic","contenu":"<div class=\"callout callout-warn\">\n        <strong>ACG = urgence thérapeutique</strong> surtout en présence de <span class=\"kw-alerte\">signes ischémiques</span> (ophtalmo, <span class=\"kw-def\">AVC</span>, ischémie membre). Le traitement repose sur la <span class=\"kw-ttt\">corticothérapie</span>, à débuter <em>sans attendre</em> la BAT si la suspicion est forte.\n      </div>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Molécules</td>\n            <td><span class=\"kw-ttt\">Prednisolone</span> per os ; <span class=\"kw-ttt\">méthylprednisolone</span> IV pour les bolus</td>\n          </tr>\n          <tr>\n            <td>Stratégie d'attaque</td>\n            <td>\n              <strong>PPR isolée :</strong> <span class=\"kw-ttt\">prednisolone 0,3 mg/kg/j</span> per os ;<br>\n              <strong>ACG sans signe <span class=\"kw-etio\">ischémique</span> :</strong> <span class=\"kw-ttt\">prednisolone 0,7 mg/kg/j</span> per os ;<br>\n              <strong>ACG avec signes ophtalmo/ischémiques :</strong> <span class=\"kw-ttt\">aspirine</span> antiagrégante + <span class=\"kw-ttt\">prednisolone 1 mg/kg/j</span> d'emblée, OU bolus IV de <span class=\"kw-ttt\">méthylprednisolone</span> 1–3 j puis relais per os (sans preuve formelle d'efficacité)\n            </td>\n          </tr>\n          <tr>\n            <td>Résultats sous CTC</td>\n            <td>\n              Efficacité souvent <span class=\"kw-clinique\">spectaculaire</span> :<br>\n              <strong>Régression clinique :</strong> en <span class=\"kw-chiffre\">24–72 h</span> ;<br>\n              <strong>Normalisation du SIB :</strong> quelques jours pour la <span class=\"kw-bio\">CRP</span>, <span class=\"kw-chiffre\">3 semaines</span> pour la <span class=\"kw-bio\">VS</span> ;<br>\n              <strong>Intérêt diagnostique :</strong> peut servir de <em>test diagnostique</em> dans la PPR ; remet en cause le diagnostic d'ACG si <span class=\"kw-alerte\">absence de corticosensibilité</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Décroissance</td>\n            <td>\n              <strong>Quand ?</strong> Après disparition des signes cliniques + régression du SIB ;<br>\n              <strong>Comment ?</strong> Diminution progressive adaptée au patient et au risque cortico (<span class=\"kw-def\">ostéoporose</span>, cataracte, <span class=\"kw-def\">diabète</span>…) ;<br>\n              <strong>Schéma usuel :</strong> paliers toutes les <span class=\"kw-chiffre\">2–4 semaines</span> :<br>\n              <span class=\"kw-chiffre\">−10 mg</span> jusqu'à<span class=\"kw-chiffre\"> 30 mg</span>/j → <span class=\"kw-chiffre\">−5 à 2,5 mg (ou −10 %)</span> jusqu'à<span class=\"kw-chiffre\"> 10 mg</span>/j → <span class=\"kw-chiffre\">−1 mg</span> au-delà\n            </td>\n          </tr>\n          <tr>\n            <td>Durée</td>\n            <td>Sevrage à viser autour de <span class=\"kw-chiffre\">18 mois</span> (entre 12 et <span class=\"kw-chiffre\">24 mois</span>)</td>\n          </tr>\n          <tr>\n            <td>Alternatives<br>(épargne cortisonique)</td>\n            <td>\n              <strong>Méthotrexate :</strong> <span class=\"kw-ci\">hors AMM</span> ;<br>\n              <strong>Tocilizumab</strong> (anti-IL-6) : prescription réservée aux spécialistes\n            </td>\n          </tr>\n          <tr>\n            <td>Pronostic</td>\n            <td>\n              Globalement <span class=\"kw-clinique\">bon</span> ; survie globale = population générale (<strong>pas de surmortalité démontrée</strong>) ;<br>\n              <strong>Cécité totale :</strong> <span class=\"kw-chiffre\">1 à 2 %</span> des ACG ;<br>\n              <strong>Rechutes :</strong> possibles, parfois tardives (jusqu'à<span class=\"kw-chiffre\"> 10 ans</span> après) ; <em>en cas de rechute à dose élevée ou avec persistance d'<span class=\"kw-clinique\">AEG</span> → discuter une néoplasie</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 202 — Biothérapies, thérapies ciblées</em></p>","frequence":3},{"id":"195-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques de la PPR","contenu":"<p>La PPR est un <strong>diagnostic d'élimination</strong> : aucun signe clinique, biologique ou d'imagerie n'est <span class=\"kw-clinique\">spécifique</span>. C'est l'<em>association</em> de critères qui fait le diagnostic.</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Terrain</td>\n            <td>\n              Sujet de <span class=\"kw-chiffre\">> 50 ans</span>, pic <span class=\"kw-chiffre\">70–80 ans</span>, prédominance féminine (<span class=\"kw-chiffre\">2F/1H</span>) ;<br>\n              <strong>Tout tableau de PPR doit faire rechercher cliniquement une ACG associée.</strong>\n            </td>\n          </tr>\n          <tr>\n            <td>Signe fonctionnel<br>(arthro-<span class=\"kw-clinique\">myalgies</span>)</td>\n            <td>\n              <strong>Topographie</strong> (« rhizome » = racine des membres) :<br>\n              <span class=\"kw-clinique\">Ceinture scapulaire :</span> épaules++, rachis cervical ;<br>\n              <span class=\"kw-clinique\">Ceinture pelvienne :</span> racines des membres inférieurs (bassin, cuisses, fesses), rachis lombaire bas ;<br>\n              <strong>Latéralité :</strong> bilatérales, le plus souvent <span class=\"kw-clinique\">symétriques</span> ;<br>\n              <strong>Horaire :</strong> <span class=\"kw-clinique\">inflammatoire</span> (enraidissement matinal <span class=\"kw-chiffre\">> 60 min</span>, réveils nocturnes 2ᵉ partie de nuit) ;<br>\n              <strong>Évolution :</strong> depuis <span class=\"kw-chiffre\">> 1 mois</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Examen clinique</td>\n            <td>\n              <strong>Impotence fonctionnelle</strong> et raideur ;<br>\n              <strong>Douleurs à la palpation</strong> des masses musculaires ;<br>\n              <strong>Douleurs à la mobilisation articulaire</strong> (glénohumérales, coxofémorales, rachis cervical et lombaire)\n            </td>\n          </tr>\n          <tr>\n            <td>Autres manifestations</td>\n            <td>\n              <strong><span class=\"kw-clinique\">Asthénie</span></strong> (<span class=\"kw-chiffre\">90 %</span>), <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">amaigrissement</span>, ± fébricule : <span class=\"kw-clinique\">AEG moins intense que dans l'ACG</span> ;<br>\n              <strong><span class=\"kw-clinique\">Arthralgies</span>, arthrites, ténosynovites périphériques</strong> beaucoup plus rares (<span class=\"kw-chiffre\">20 %</span>) : mains, poignets\n            </td>\n          </tr>\n          <tr>\n            <td>Drapeaux rouges 🚩<br>(<em>contre</em> PPR)</td>\n            <td>\n              <span class=\"kw-alerte\">Signes généraux intenses</span> ; absence d'atteinte des épaules ;<br>\n              <span class=\"kw-alerte\">Organomégalie</span> : <span class=\"kw-clinique\">adénopathies</span>, splénomégalie, hépatomégalie ;<br>\n              <span class=\"kw-alerte\">Atteinte des petits vaisseaux</span> : <span class=\"kw-def\">purpura</span>, <span class=\"kw-def\">syndrome néphritique</span>/néphrotique, mononeuropathie multiple, polynévrite ;<br>\n              <span class=\"kw-alerte\">Absence de réponse</span> après quelques jours de <span class=\"kw-ttt\">corticothérapie</span> ;<br>\n              <span class=\"kw-alerte\">Absence de SIB</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":2},{"id":"195-11","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principaux diagnostics différentiels de la PPR","contenu":"<p>La PPR étant un diagnostic d'<span class=\"kw-clinique\">élimination</span>, le bilan paraclinique vise surtout à exclure les DD.</p>\n      <table >\n        <thead>\n          <tr><th>DD</th><th>Éléments distinctifs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>PR du sujet âgé</td>\n            <td>\n              DD difficile : la PR du sujet âgé débute fréquemment de manière rhizomélique (<span class=\"kw-chiffre\">40 %</span>), et la PPR peut comporter des ténosynovites/arthrites périphériques (<span class=\"kw-chiffre\">20 %</span>).<br>\n              <strong>Différence :</strong> <span class=\"kw-imagerie\">érosions RX</span> + présence d'<span class=\"kw-bio\">ACPA</span> font retenir la PR ;<br>\n              <span class=\"kw-ci\">Le FR seul est fréquemment + sans valeur pathologique chez le sujet âgé</span> ❌.\n            </td>\n          </tr>\n          <tr>\n            <td>Cancer<br>(syndrome PPR <span class=\"kw-etio\">paranéoplasique</span>)</td>\n            <td>\n              Possible avec cancers solides, lymphomes, hémopathies.<br>\n              <strong>Éléments évocateurs :</strong> <span class=\"kw-clinique\">AEG</span> importante, autres signes d'appel ;<br>\n              <strong>Justifie la <span class=\"kw-imagerie\">RXT</span> dans le bilan initial</strong> d'une PPR.\n            </td>\n          </tr>\n          <tr>\n            <td>Affections musculaires<br>(polymyosite++)</td>\n            <td>\n              Atteinte musculaire prédominante.<br>\n              <strong>Évocateurs :</strong> déficit musculaire + élévation des enzymes musculaires + auto-Ac ;<br>\n              <strong>Examen-clé :</strong> <span class=\"kw-bio\">CPK</span> (normaux dans la PPR)\n            </td>\n          </tr>\n          <tr>\n            <td>RS3PE<br><em>(polyarthrite œdémateuse)</em></td>\n            <td>\n              <strong>Manifestations :</strong> polysynovite + <span class=\"kw-clinique\">œdèmes</span> des extrémités, blancs, prenant le godet ;<br>\n              <strong>Évolution :</strong> résolutive en <span class=\"kw-chiffre\">12–18 mois</span>, très <span class=\"kw-clinique\">corticosensible</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Autres</td>\n            <td>\n              <strong>Rhumatismes microcristallins :</strong> chondrocalcinose (RX, écho, ponction articulaire) ;<br>\n              <strong><span class=\"kw-def\">Spondyloarthrite</span> du sujet âgé :</strong> exceptionnelle ;<br>\n              <strong>Connectivites :</strong> <span class=\"kw-def\">Lupus</span>, Gougerot-Sjögren (rare début rhizomélique) ;<br>\n              <strong>Maladie de Parkinson, dysthyroïdies, ostéomalacie ;</strong><br>\n              <strong><span class=\"kw-clinique\">Myalgies</span> iatrogènes :</strong> <span class=\"kw-ttt\">statines, β-bloquants, antiparkinsoniens, ipilimumab (anti-CTLA-4), nivolumab (anti-PD-1)</span> ;<br>\n              <strong>Mécaniques :</strong> coiffe des rotateurs, coxarthrose, arthrose glénohumérale, tendinopathies\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 196 — <span class=\"kw-def\">Polyarthrite rhumatoïde</span> · 194 — <span class=\"kw-def\">Lupus</span> - SAPL · 211 — Sarcoïdose</em></p>","frequence":0},{"id":"195-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires utiles au diagnostic","contenu":"<div class=\"callout callout-info\">\n        Aucun examen ne porte le diagnostic de PPR à lui seul : pas de <span class=\"kw-imagerie\">signe pathognomonique en imagerie</span>, pas de marqueur biologique spécifique. Le bilan vise à <strong>objectiver le SIB</strong> et <strong>éliminer les DD</strong>.\n      </div>\n      <table >\n        <thead>\n          <tr><th></th><th>Systématique</th><th>Selon contexte</th><th>Pré-thérapeutique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <span class=\"kw-bio\">Hémogramme, CRP, VS/fibrinogène</span> ;<br>\n              <span class=\"kw-bio\">Iono, calcémie</span> ;<br>\n              <span class=\"kw-bio\">Urée, créat, DFG</span> ;<br>\n              <span class=\"kw-bio\">Bilan hépatique</span> ;<br>\n              <span class=\"kw-bio\">BU</span> ;<br>\n              <span class=\"kw-bio\">ACPA/anti-CCP ± FR</span>\n            </td>\n            <td>\n              <span class=\"kw-bio\">CPK, auto-Ac myosites</span> ;<br>\n              <span class=\"kw-bio\">TSH</span> ;<br>\n              <span class=\"kw-bio\">EPS</span> ;<br>\n              <span class=\"kw-bio\">AAN, ANCA…</span>\n            </td>\n            <td>\n              <span class=\"kw-bio\">Glycémie à jeun</span> ;<br>\n              <span class=\"kw-bio\">Bilan lipidique</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <span class=\"kw-imagerie\">RXT</span> ;<br>\n              <span class=\"kw-imagerie\">RX épaules</span> (face, rot. médiale, rot. externe) ;<br>\n              <span class=\"kw-imagerie\">RX bassin de face</span>\n            </td>\n            <td>\n              <span class=\"kw-imagerie\">Échographie épaule/hanche</span> ;<br>\n              <span class=\"kw-imagerie\">TEP-TDM</span>\n            </td>\n            <td>\n              <span class=\"kw-imagerie\">Ostéodensitométrie</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Résultats attendus dans la PPR</strong> :</p>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Résultats / objectifs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Bilan inflammatoire</td>\n            <td>\n              <strong>Anomalies de SIB :</strong> <span class=\"kw-bio\">VS, CRP, fibrinogène ↑</span> ; anémie inflammatoire ; thrombocytose ;<br>\n              <strong><span class=\"kw-bio\">CPK</span> normales</strong> (élimine polymyosite) ;<br>\n              <strong><span class=\"kw-bio\">TSH</span> normale</strong> (élimine dysthyroïdie)\n            </td>\n          </tr>\n          <tr>\n            <td>FR + anti-CCP</td>\n            <td>\n              <strong>Objectif :</strong> éliminer une <span class=\"kw-clinique\">PR à début rhizomélique</span> ;<br>\n              <span class=\"kw-ci\">30 % des sujets âgés ont un FR + sans avoir de PR</span> ❌ — les anti-CCP sont beaucoup plus spécifiques de la PR\n            </td>\n          </tr>\n          <tr>\n            <td>RX articulaires (épaules, bassin)</td>\n            <td><span class=\"kw-imagerie\">Normales</span> au cours de la PPR — <span class=\"kw-ci\">pas de destruction articulaire</span> ❌</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">Échographie</span> ceintures<br>(mode B + <span class=\"kw-imagerie\">doppler</span>)</td>\n            <td>\n              Bursite sub-acromio-deltoïdienne, bursite trochantérienne, ténosynovite du long biceps, épanchements, synovites ;<br>\n              <strong>Spécificité :</strong> anomalies fréquentes au vieillissement → évocateur de PPR si <span class=\"kw-clinique\">bilatéral</span> + caractère <span class=\"kw-clinique\">inflammatoire en doppler puissance</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\">TEP-TDM</span></td>\n            <td>\n              <strong>Indication :</strong> réservée aux doutes diagnostiques ;<br>\n              <strong>Fixations évocatrices (non pathognomoniques) :</strong> <span class=\"kw-imagerie\">bilatérales</span>, sites asymptomatiques inclus, ceintures scapulaire/pelvienne, bursites <span class=\"kw-imagerie\">interépineuses</span> cervicales/thoraciques/lombaires\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"195-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement de la PPR et son pronostic","contenu":"<div class=\"callout callout-info\">\n        La <span class=\"kw-clinique\">PPR isolée</span> n'est <strong>pas une urgence thérapeutique</strong> au sens strict (contrairement à l'ACG avec signes ischémiques). Le traitement repose sur la <span class=\"kw-ttt\">corticothérapie à dose faible</span>, avec un effet souvent spectaculaire dès <span class=\"kw-chiffre\">24–72 h</span> (utilisé comme <em>test diagnostique</em>).\n      </div>\n      <table >\n        <thead>\n          <tr><th>Phase</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Attaque</td>\n            <td>\n              <strong>Molécule :</strong> <span class=\"kw-ttt\">prednisolone</span> per os ;<br>\n              <strong>Posologie :</strong> <span class=\"kw-ttt\">0,3 mg/kg/j</span> (plus faible que dans l'ACG)\n            </td>\n          </tr>\n          <tr>\n            <td>Résultats</td>\n            <td>\n              Efficacité <span class=\"kw-clinique\">spectaculaire</span> en <span class=\"kw-chiffre\">24–72 h</span> ;<br>\n              Normalisation du SIB en quelques jours (<span class=\"kw-bio\">CRP</span>) à<span class=\"kw-chiffre\"> 3 semaines</span> (<span class=\"kw-bio\">VS</span>) ;<br>\n              <strong>Test diagnostique :</strong> remet en cause le diagnostic en l'absence de corticosensibilité\n            </td>\n          </tr>\n          <tr>\n            <td>Décroissance</td>\n            <td>\n              <strong>Quand ?</strong> Après disparition des signes cliniques + régression du SIB ;<br>\n              <strong>Schéma :</strong> paliers toutes les <span class=\"kw-chiffre\">2–4 semaines</span> : −<span class=\"kw-chiffre\">10 mg</span> →<span class=\"kw-chiffre\"> 30 mg</span>/j ; puis −<span class=\"kw-chiffre\">5 à 2,5 mg</span> (ou −<span class=\"kw-chiffre\">10 %</span>) →<span class=\"kw-chiffre\"> 10 mg</span>/j ; puis −<span class=\"kw-chiffre\">1 mg</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Durée</td>\n            <td>Sevrage à viser autour de <span class=\"kw-chiffre\">18 mois</span> (<span class=\"kw-chiffre\">12–24 mois</span>)</td>\n          </tr>\n          <tr>\n            <td>Alternatives<br>(épargne cortisonique)</td>\n            <td>\n              <span class=\"kw-ttt\">Méthotrexate</span> hors AMM ;<br>\n              <span class=\"kw-ttt\">Tocilizumab</span> (anti-IL-6) — réservé aux spécialistes\n            </td>\n          </tr>\n          <tr>\n            <td>Pronostic</td>\n            <td>\n              Évolution favorable en <span class=\"kw-chiffre\">12–24 mois</span> dans la majorité des cas ;<br>\n              <strong>Corticodépendance</strong> (sevrage impossible) peu fréquente : <span class=\"kw-chiffre\">20 %</span> ;<br>\n              <strong>Morbidité liée à la <span class=\"kw-ttt\">corticothérapie</span></strong> (<span class=\"kw-def\">ostéoporose</span>, cataracte, <span class=\"kw-def\">diabète</span>, infections) → prévention précoce ;<br>\n              <strong>Rechutes :</strong><span class=\"kw-chiffre\"> 20–50 %</span>, parfois tardives (jusqu'à<span class=\"kw-chiffre\"> 10 ans</span>), à surveiller (peut basculer en ACG)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 202 — Biothérapies, thérapies ciblées</em></p>","frequence":1},{"id":"195-14","rang":"B","rubrique":"Définition","titre":"Connaître la définition de l’artérite de Takayasu","contenu":"<p><span class=\"kw-def\">Vascularite granulomateuse</span> des vaisseaux de <span class=\"kw-def\">gros calibre</span>, touchant <strong>l'<span class=\"kw-clinique\">aorte et ses gros troncs</span></strong>, ainsi que <strong>l'<span class=\"kw-clinique\">artère pulmonaire</span></strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Synonymes</td>\n            <td>« Maladie des femmes sans pouls » ; « Syndrome de l'arc aortique »</td>\n          </tr>\n          <tr>\n            <td>Artères touchées</td>\n            <td>\n              Dans <span class=\"kw-chiffre\">60–90 %</span> des cas :<br>\n              <strong>Aorte :</strong> ascendante et/ou descendante ;<br>\n              <strong>Branches :</strong> <span class=\"kw-clinique\">artères sous-clavières</span>, branches de la <span class=\"kw-clinique\">carotide</span>\n            </td>\n          </tr>\n          <tr>\n            <td>Fréquence</td>\n            <td><span class=\"kw-clinique\">Très rare</span> en France</td>\n          </tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 193 — <span class=\"kw-def\">Vascularite</span> systémique</em></p>","frequence":0},{"id":"195-15","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales caractéristiques de l’artérite de Takayasu (généralités)","contenu":"<p>Le profil-type du Takayasu est <strong>diamétralement opposé</strong> à celui de l'ACG : <em>femme jeune asiatique</em> <span class=\"kw-bio\">vs</span> <em>sujet âgé caucasien</em>. La maladie évolue en <strong>2 phases successives</strong>.</p>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Âge / sex-ratio</td>\n            <td>\n              <span class=\"kw-clinique\">Femme jeune</span> (<span class=\"kw-chiffre\">20–35 ans</span>), <span class=\"kw-chiffre\">9F/1H</span> ;<br>\n              <em>Hommes : plus d'atteinte de l'aorte descendante et abdominale</em>\n            </td>\n          </tr>\n          <tr>\n            <td>Ethnie</td>\n            <td>\n              <span class=\"kw-clinique\">Patientes asiatiques</span> : nette prédominance ethnique ;<br>\n              Formes moins sévères et diagnostic plus tardif chez les sujets caucasiens\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Phase inflammatoire initiale (pré-occlusive)</strong> — durée : <span class=\"kw-chiffre\">quelques semaines à quelques mois</span></p>\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Signes généraux</td>\n            <td><span class=\"kw-clinique\">Fièvre</span>, <span class=\"kw-clinique\">AEG</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">anorexie</span></td>\n          </tr>\n          <tr>\n            <td>Manifestations spécifiques</td>\n            <td>\n              <strong>Rhumatologiques :</strong> <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">arthralgies</span>, mono/polyarthrites, syndrome de PPR ;<br>\n              <strong>Sérites :</strong> épanchements pleuraux ou péricardiques ;<br>\n              <strong>Cutanées :</strong> érythème noueux, <span class=\"kw-clinique\">rash</span> ;<br>\n              <strong>Oculaires :</strong> douleurs, troubles de la vue ;<br>\n              <strong>Carotidodynies ⭐</strong> : douleurs le long des carotides\n            </td>\n          </tr>\n          <tr>\n            <td>Biologie</td>\n            <td><span class=\"kw-def\">Syndrome inflammatoire</span> <span class=\"kw-clinique\">chronique</span></td>\n          </tr>\n          <tr>\n            <td>Évolution</td>\n            <td>Récidive ou disparition → puis phase occlusive</td>\n          </tr>\n          <tr>\n            <td>PEC</td>\n            <td>\n              <span class=\"kw-ttt\">Corticothérapie</span><span class=\"kw-chiffre\"> 12–24 mois</span> (efficace <span class=\"kw-chiffre\">> 50 %</span> des cas) ;<br>\n              <span class=\"kw-ttt\">Immunosuppresseur</span> souvent nécessaire (corticorésistance ou épargne cortisonique) : <span class=\"kw-ttt\">méthotrexate, azathioprine, mycophénolate mofétil</span>, plus rarement <span class=\"kw-ttt\">cyclophosphamide</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Phase chronique occlusive</strong> — survient <span class=\"kw-chiffre\">plusieurs années</span> après la phase inflammatoire ; le diagnostic est <strong>souvent posé à ce stade</strong> (tardif).</p>\n      <table >\n        <thead>\n          <tr><th>Territoire</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Syndrome de l'arc aortique<br>(< 40 ans)</td>\n            <td>\n              <strong>Présentation :</strong> <span class=\"kw-def\">HTA</span>, claudication intermittente des membres supérieurs, ± <span class=\"kw-clinique\">céphalée</span>, diplopie, <span class=\"kw-clinique\">vertiges</span> ;<br>\n              <strong>Examen :</strong> <span class=\"kw-clinique\">asymétrie tensionnelle</span>, <span class=\"kw-clinique\">diminution/abolition d'un pouls</span> (huméral++), souffle sus-claviculaire\n            </td>\n          </tr>\n          <tr>\n            <td>TSAO</td>\n            <td>Syndrome de l'arc aortique très évocateur (voir ci-dessus)</td>\n          </tr>\n          <tr>\n            <td>Artères viscérales abdominales</td>\n            <td>AAA ; <span class=\"kw-alerte\">HTA rénovasculaire</span> ; coarctation de l'aorte ; <span class=\"kw-clinique\">diarrhée</span> ; <span class=\"kw-clinique\">douleurs abdominales</span></td>\n          </tr>\n          <tr>\n            <td>Coronaires</td>\n            <td>Coronarite ostiale ; <span class=\"kw-def\">insuffisance cardiaque</span> ; <span class=\"kw-alerte\">insuffisance aortique</span> par dilatation de l'anneau (<span class=\"kw-chiffre\">10–25 %</span>)</td>\n          </tr>\n          <tr>\n            <td>Artère pulmonaire</td>\n            <td><span class=\"kw-clinique\">Toux</span> ; <span class=\"kw-alerte\">hémoptysie</span> ; <span class=\"kw-alerte\">HTA pulmonaire</span></td>\n          </tr>\n          <tr>\n            <td>SNC</td>\n            <td>Amaurose, scotome, cécité ; manifestations rares : <span class=\"kw-alerte\">AVC, IDM</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">\n        <strong>Particularité Takayasu.</strong> Les symptômes peuvent être <span class=\"kw-clinique\">transitoires, à éclipses</span>, survenant lors d'<span class=\"kw-clinique\">efforts</span> ou de <span class=\"kw-clinique\">postures</span>. Les formes longtemps indolentes ou peu spécifiques expliquent le <span class=\"kw-alerte\">retard diagnostique fréquent</span>. La PEC repose souvent sur des <span class=\"kw-ttt\">gestes de revascularisation</span> (endovasculaires ou chirurgicaux).\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 224 — <span class=\"kw-def\">HTA</span> · 205 — <span class=\"kw-clinique\">Hémoptysie</span> · 339 — Syndrome coronarien aiguë · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":4},{"id":"195-16","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place de l’anatomie pathologique pour le diagnostic de l’ACG et de la maladie de Takayasu","contenu":"<div class=\"callout callout-info\">\n        <strong>Place actuelle :</strong> grâce aux <span class=\"kw-imagerie\">progrès de l'imagerie</span> (<span class=\"kw-imagerie\">écho-<span class=\"kw-imagerie\">doppler</span></span>, <span class=\"kw-imagerie\">TEP-TDM</span>, <span class=\"kw-imagerie\">angio-<span class=\"kw-imagerie\">IRM</span></span>), le diagnostic <span class=\"kw-imagerie\">histologique</span> est de <em>moins en moins nécessaire</em> dans l'ACG comme dans le Takayasu — il n'est plus systématique. L'imagerie peut se substituer à la BAT dans les centres experts (collège de Rhumato), tandis que le collège de Médecine interne maintient la BAT en 1ʳᵉ intention.\n      </div>\n      <p>Comparaison histologique des deux vascularites :</p>\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>ACG (Horton)</th><th>Takayasu</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Type d'atteinte</td>\n            <td><span class=\"kw-bio\">Panartérite</span> des 3 tuniques</td>\n            <td>Aspects <span class=\"kw-bio\">proches</span> de l'ACG, panartérite des 3 tuniques</td>\n          </tr>\n          <tr>\n            <td>Infiltrat inflammatoire</td>\n            <td>\n              <strong>Cellules mononuclées</strong> (<span class=\"kw-bio\">lymphocytes</span>, macrophages) ;<br>\n              <strong>Cellules géantes mononucléées</strong> = caractéristique mais <span class=\"kw-clinique\">inconstantes</span>\n            </td>\n            <td>\n              <strong>Multifocal et segmentaire</strong> ;<br>\n              <span class=\"kw-clinique\">Moins intense</span> que dans Horton\n            </td>\n          </tr>\n          <tr>\n            <td>Fibrose</td>\n            <td>Présente, modérée</td>\n            <td><span class=\"kw-bio\">Plus importante</span> que dans Horton ⭐</td>\n          </tr>\n          <tr>\n            <td>Lésions caractéristiques</td>\n            <td>\n              <strong>Fragmentation de la <span class=\"kw-bio\">LEI</span></strong> (limitante élastique interne) ;<br>\n              <strong>Hyperplasie intimale</strong> → sténose/occlusion ;<br>\n              Diminution de la lumière artérielle\n            </td>\n            <td>\n              Lésions <span class=\"kw-clinique\">aspécifiques</span> possibles ;<br>\n              Lésions <span class=\"kw-clinique\">cicatricielles</span> peuvent être les seules visibles\n            </td>\n          </tr>\n          <tr>\n            <td>Élément <em>négatif</em> important</td>\n            <td><span class=\"kw-ci\">PAS de nécrose fibrinoïde</span> ❌</td>\n            <td>Idem (<span class=\"kw-def\">vascularite</span> des gros vaisseaux, pas de petits)</td>\n          </tr>\n          <tr>\n            <td>Sensibilité BAT (ACG)</td>\n            <td colspan=\"2\"><span class=\"kw-bio\">50–90 %</span> ; <span class=\"kw-chiffre\">1/3 normales</span> car atteinte segmentaire focale → <strong>une BAT négative n'élimine pas le diagnostic</strong></td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Modalités pratiques BAT (rappel obj-7) :</strong> anesthésie locale ; prélèvement <span class=\"kw-chiffre\">> 0,5–1 cm</span> ; fixation formol ; côté le plus symptomatique ; ne doit <span class=\"kw-clinique\">pas retarder le traitement</span> ; sensibilité conservée jusqu'à<span class=\"kw-chiffre\"> 2 semaines</span> de CTC.</p>","frequence":2}],"astuces":[],"strategie":{"urgence":"<p><strong>ACG = urgence thérapeutique <span class=\"q\">— surtout si signes ischémiques</span></strong></p><p>Débuter le traitement <strong>sans attendre la BAT</strong> (sa sensibilité reste conservée jusqu'à <span class=\"kw-chiffre\">2 semaines</span> de <span class=\"kw-ttt\">corticothérapie</span>)</p><ul><li>Complications <span class=\"kw-clinique\">ophtalmologiques</span> = principale complication ischémique (<span class=\"kw-chiffre\">5–30 %</span>) : <span class=\"kw-alerte\">BAV</span>, <span class=\"kw-alerte\">amaurose</span>, <span class=\"kw-alerte\">diplopie</span></li><li>Tout signe ophtalmo chez un suspect d'ACG → <span class=\"kw-ttt\">corticothérapie</span> en urgence pour prévenir la <span class=\"kw-alerte\">cécité bilatérale définitive</span></li></ul><p><strong>PPR isolée <span class=\"q\">— pas une urgence au sens strict</span></strong></p><p>Rechercher systématiquement une <span class=\"kw-def\">ACG</span> associée (<span class=\"kw-chiffre\">20 %</span> des PPR), potentiellement urgente</p><ul><li>Absence de signe <span class=\"kw-etio\">ischémique</span> → délai de mise en route moins contraint</li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">BAV unilatérale</span> indolore brutale ou <span class=\"kw-alerte\">amaurose</span> brutale → risque de <span class=\"kw-alerte\">cécité totale définitive</span></li><li><span class=\"kw-clinique\">Diplopie</span> / <span class=\"kw-alerte\">paralysie oculomotrice</span></li><li><span class=\"kw-alerte\">AVC ischémique</span> ou <span class=\"kw-alerte\">AIT</span> (territoire vertébro-carotidien, <span class=\"kw-chiffre\">5–7 %</span>)</li><li>Claudication de la <span class=\"kw-clinique\">mâchoire</span> ou de la <span class=\"kw-clinique\">langue</span> → risque de <span class=\"kw-alerte\">nécrose linguale</span> ; <span class=\"kw-alerte\">nécrose du scalp</span></li><li>Atteinte aortique : <span class=\"kw-alerte\">dissection aortique</span>, <span class=\"kw-alerte\">anévrysme</span>, <span class=\"kw-alerte\">insuffisance aortique</span></li><li><span class=\"kw-alerte\">Infarctus mésentérique</span> (atteinte digestive)</li></ul>","principes":"<p>La <span class=\"kw-ttt\">corticothérapie</span> est la pierre angulaire ; la dose est <strong>adaptée à la sévérité</strong> du tableau. Débuter <strong>sans attendre la BAT</strong> si la suspicion est forte. La <span class=\"kw-clinique\">corticosensibilité</span> spectaculaire en <span class=\"kw-chiffre\">24–72 h</span> sert de <span class=\"kw-def\">test diagnostique</span> (surtout dans la PPR).</p><p><strong>PPR isolée</strong></p><ul><li><span class=\"kw-ttt\">Prednisolone</span> <span class=\"kw-chiffre\">0,3 mg/kg/j</span> per os (dose faible)</li></ul><p><strong>ACG sans signe ischémique</strong></p><ul><li><span class=\"kw-ttt\">Prednisolone</span> <span class=\"kw-chiffre\">0,7 mg/kg/j</span> per os</li></ul><p><strong>ACG avec signes ophtalmologiques / ischémiques <span class=\"q\">— urgence</span></strong></p><p>Débuter sans attendre la BAT</p><ul><li><span class=\"kw-ttt\">Aspirine</span> antiagrégante + <span class=\"kw-ttt\">prednisolone</span> <span class=\"kw-chiffre\">1 mg/kg/j</span> per os d'emblée</li><li>OU <span class=\"kw-ttt\">bolus IV de méthylprednisolone</span> <span class=\"kw-chiffre\">1–3 j</span> puis relais per os</li></ul><p><strong>Décroissance et durée</strong></p><ul><li>Décroissance progressive après disparition des signes + régression du <span class=\"kw-def\">syndrome inflammatoire</span></li><li>Paliers toutes les <span class=\"kw-chiffre\">2–4 semaines</span> ; sevrage visé autour de <span class=\"kw-chiffre\">18 mois</span> (<span class=\"kw-chiffre\">12–24 mois</span>)</li></ul><p><strong>Épargne cortisonique (alternatives)</strong></p><ul><li><span class=\"kw-ttt\">Méthotrexate</span> (<span class=\"kw-ci\">hors AMM</span>)</li><li><span class=\"kw-ttt\">Tocilizumab</span> (anti-IL-6), réservé aux spécialistes</li></ul><p><strong>Artérite de Takayasu</strong></p><ul><li>Phase inflammatoire : <span class=\"kw-ttt\">corticothérapie</span> <span class=\"kw-chiffre\">12–24 mois</span> (efficace &gt; <span class=\"kw-chiffre\">50 %</span>)</li><li><span class=\"kw-ttt\">Immunosuppresseur</span> souvent nécessaire : <span class=\"kw-ttt\">méthotrexate</span>, <span class=\"kw-ttt\">azathioprine</span>, <span class=\"kw-ttt\">mycophénolate mofétil</span>, plus rarement <span class=\"kw-ttt\">cyclophosphamide</span></li><li>Phase occlusive : <span class=\"kw-ttt\">gestes de revascularisation</span> (endovasculaires ou chirurgicaux)</li></ul>","suivi":"<p><strong>Efficacité du traitement</strong></p><ul><li>Régression clinique en <span class=\"kw-chiffre\">24–72 h</span></li><li>Normalisation du SIB : <span class=\"kw-bio\">CRP</span> en quelques jours, <span class=\"kw-bio\">VS</span> en <span class=\"kw-chiffre\">3 semaines</span></li></ul><p><strong>Complications de la <span class=\"kw-ttt\">corticothérapie</span> <span class=\"q\">— prévention précoce</span></strong></p><p>Mesures d'épargne et de prévention dès l'instauration</p><ul><li><span class=\"kw-def\">Ostéoporose</span>, <span class=\"kw-def\">cataracte</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">infections</span></li></ul><p><strong>Rechutes</strong></p><ul><li>Fréquentes (<span class=\"kw-chiffre\">20–50 %</span>), parfois tardives (jusqu'à <span class=\"kw-chiffre\">10 ans</span>)</li><li>Peuvent changer de mode : <span class=\"kw-clinique\">PPR rechutant sous forme d'ACG</span></li><li>Rechute à dose élevée ou avec <span class=\"kw-clinique\">AEG</span> persistante → discuter une <span class=\"kw-etio\">néoplasie</span></li></ul><p><strong>Pronostic</strong></p><ul><li>Globalement <span class=\"kw-clinique\">bon</span> : survie identique à la population générale (pas de surmortalité)</li><li><span class=\"kw-def\">Corticodépendance</span> peu fréquente (<span class=\"kw-chiffre\">~20 %</span>, surtout PPR)</li><li><span class=\"kw-alerte\">Cécité totale</span> : <span class=\"kw-chiffre\">1–2 %</span> des ACG</li></ul>"},"liensGlobaux":[{"href":"https://www.lecofer.org/item-cours-1-18-6.php","label":"Collège (COFER) — Item cours 1 18 6"},{"href":"https://radiopaedia.org/articles/giant-cell-arteritis","label":"Radiopaedia : Giant cell arteritis"},{"href":"https://www.imaios.com/fr/e-anatomy/structures-anatomiques/artere-temporale-superficielle-1553667484","label":"IMAIOS e-Anatomy — Artere temporale superficielle 1553667484"},{"href":"https://www.lecofer.org/item-cours-1-18-6.php#ch_8","label":"Collège (COFER) — Item cours 1 18 6"},{"href":"https://radiopaedia.org/articles/takayasu-arteritis","label":"Radiopaedia : Takayasu arteritis"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Tableau ACG / PPR : signes ischémiques ou ophtalmologiques ? — Sujet de plus de 50 ans avec syndrome inflammatoire biologique","detail":"<h4>CAT — orientation thérapeutique devant une ACG / PPR — Sujet de plus de <span class=\"kw-chiffre\">50 ans</span> avec syndrome inflammatoire biologique</h4>","branches":[{"to":"t-acg-compliquee","label":"Oui — BAV, amaurose, diplopie, AVC/AIT, ischémie de membre","color":"red"},{"to":"q-acg-ppr","label":"Non — pas de signe ischémique","color":"blue"}]},{"id":"t-acg-compliquee","kind":"terminal","label":"ACG compliquée — urgence thérapeutique","color":"red","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-alerte\">BAV unilatérale</span> indolore brutale (<span class=\"kw-chiffre\">15 %</span>), <span class=\"kw-alerte\">amaurose</span> brutale transitoire</li><li><span class=\"kw-clinique\">Flou visuel</span>, <span class=\"kw-clinique\">scotome</span>, <span class=\"kw-alerte\">diplopie</span> (paralysie oculomotrice)</li><li><span class=\"kw-alerte\">AVC ischémique</span> / <span class=\"kw-alerte\">AIT</span>, ischémie de membre, <span class=\"kw-alerte\">infarctus mésentérique</span></li></ul><h4>Étiologies ophtalmologiques</h4><ul><li><span class=\"kw-etio\">NOIAA</span> (neuropathie optique ischémique antérieure aiguë) — la principale</li><li><span class=\"kw-etio\">OACR</span> (occlusion de l'artère centrale de la rétine, <span class=\"kw-chiffre\">2 %</span>)</li><li><span class=\"kw-etio\">NOIPA</span> (postérieure, rare)</li></ul><h4>Traitement — urgence thérapeutique</h4><ul><li><span class=\"kw-ttt\">Aspirine</span> à dose antiagrégante + <span class=\"kw-ttt\">prednisolone</span> <span class=\"kw-chiffre\">1 mg/kg/j</span> per os d'emblée</li><li>OU <span class=\"kw-ttt\">bolus IV de méthylprednisolone</span> <span class=\"kw-chiffre\">1–3 j</span> puis relais per os</li><li>Débuter <strong>sans attendre la BAT</strong> (sensibilité conservée jusqu'à <span class=\"kw-chiffre\">2 semaines</span> de <span class=\"kw-ttt\">corticothérapie</span>)</li></ul><h4>Enjeu</h4><ul><li>Prévenir l'<span class=\"kw-alerte\">atteinte controlatérale</span> et la <span class=\"kw-alerte\">cécité totale définitive</span> (<span class=\"kw-chiffre\">1–2 %</span> de cécité dans l'ACG)</li></ul><h4>Renvoi</h4><ul><li>Item 82 (anomalie aiguë de la vision) · Item 340 (<span class=\"kw-alerte\">AVC</span>)</li></ul>"},{"id":"q-acg-ppr","kind":"decision","label":"Signes vasculaires crâniens d'ACG présents ? — Céphalée temporale résistante, claudication de la mâchoire, anomalie de l'artère temporale","branches":[{"to":"t-acg-simple","label":"Oui — atteinte crânienne d'ACG","color":"amber"},{"to":"t-ppr","label":"Non — arthro-myalgies des ceintures isolées","color":"green"}]},{"id":"t-acg-simple","kind":"terminal","label":"ACG non compliquée","color":"amber","detail":"<h4>Confirmation</h4><ul><li><span class=\"kw-imagerie\">Écho-doppler des axes vasculaires</span> en 1re intention : <span class=\"kw-imagerie\">signe du halo</span> (Sp <span class=\"kw-chiffre\">100 %</span> si bilatéral)</li><li><span class=\"kw-imagerie\">BAT</span> = examen de référence, non indispensable si imagerie compatible ; <strong>ne doit pas retarder le traitement</strong></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Prednisolone</span> <span class=\"kw-chiffre\">0,7 mg/kg/j</span> per os ; corticosensibilité spectaculaire en <span class=\"kw-chiffre\">24–72 h</span></li></ul><h4>Réflexe</h4><ul><li>Rechercher des symptômes de <span class=\"kw-def\">PPR</span> associée (<span class=\"kw-chiffre\">40–60 %</span> des ACG)</li></ul><h4>Renvoi</h4><ul><li>Item 202 (biothérapies — tocilizumab anti-IL-6)</li></ul>"},{"id":"t-ppr","kind":"terminal","label":"PPR isolée","color":"green","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-clinique\">Arthro-myalgies</span> bilatérales symétriques des <span class=\"kw-clinique\">ceintures scapulaire et pelvienne</span></li><li>Raideur matinale <span class=\"kw-chiffre\">&gt; 60 min</span>, évolution depuis <span class=\"kw-chiffre\">&gt; 1 mois</span></li><li><strong>Pas de vascularite</strong> : aucune atteinte hors appareil locomoteur</li></ul><h4>Bilan</h4><ul><li>Objectiver le <span class=\"kw-def\">syndrome inflammatoire</span> et éliminer les différentiels : <span class=\"kw-bio\">FR / anti-CCP</span>, <span class=\"kw-bio\">CPK</span>, <span class=\"kw-bio\">TSH</span> (normaux dans la PPR)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Prednisolone</span> <span class=\"kw-chiffre\">0,3 mg/kg/j</span> per os (dose faible) ; corticosensibilité = <span class=\"kw-def\">test diagnostique</span></li></ul><h4>Vigilance</h4><ul><li>Tout tableau de PPR doit faire rechercher cliniquement une <span class=\"kw-def\">ACG</span> associée (<span class=\"kw-chiffre\">20 %</span>) ; rechute possible sur un <span class=\"kw-alerte\">mode ACG</span></li></ul>"}]},"cards":[{"i":"7e0ba50e3278","n":195,"o":"195-1","u":"Définition","t":"Connaître la définition de l’artérite à cellules géantes (ACG)","q":"Quel est le lien entre l'artérite à cellules géantes (maladie de Horton) et la pseudopolyarthrite rhizomélique (PPR) ?","a":"<p>L'ACG (maladie de Horton) et la PPR sont considérées comme <strong>deux expressions cliniques de la même maladie</strong>. Elles peuvent se succéder, être intriquées (environ 15 % des cas) et partagent des facteurs immunogénétiques communs (tels que HLA-DR4 et une hyperproduction d'IL-6).</p>"},{"i":"874785d12971","n":195,"o":"195-1","u":"Définition","t":"Connaître la définition de l’artérite à cellules géantes (ACG)","q":"Quelle est la définition de l'artérite à cellules géantes (ACG) ?","a":"<p>L'ACG est une <strong>vascularite granulomateuse</strong> qui affecte préférentiellement les <strong>vaisseaux de gros calibre</strong> chez le sujet de <strong>plus de 50 ans</strong> (avec un pic de fréquence entre 70 et 80 ans).</p>"},{"i":"af064a21c915","n":195,"o":"195-1","u":"Définition","t":"Connaître la définition de l’artérite à cellules géantes (ACG)","q":"Quels sont les principaux territoires vasculaires atteints par l'artérite à cellules géantes ?","a":"<ul><li>L'<strong>aorte</strong> et ses gros troncs.</li><li>Les vaisseaux à destinée céphalique : branches de l'artère <strong>carotide externe</strong> (notamment les artères temporales), mais aussi la carotide interne et les artères vertébrales.</li><li>Les vaisseaux des membres supérieurs : artères <strong>sous-clavières</strong> et <strong>axillaires</strong>.</li></ul>"},{"i":"1f1dc33cef9f","n":195,"o":"195-10","u":"Diagnostic positif","t":"Connaître les signes cliniques de la PPR","q":"Quel est le profil épidémiologique typique d'un patient atteint de pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>La pseudo-polyarthrite rhizomélique (PPR) touche généralement les sujets de <strong>plus de 50 ans</strong>, avec un pic entre <strong>70 et 80 ans</strong>. Il existe une prédominance féminine (sex-ratio d'environ <strong>2 femmes pour 1 homme</strong>).</p>"},{"i":"27c5e252fc4c","n":195,"o":"195-10","u":"Diagnostic positif","t":"Connaître les signes cliniques de la PPR","q":"Quelles sont les caractéristiques des signes fonctionnels (douleurs arthro-musculaires) de la pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>Les douleurs dans la PPR se caractérisent par :</p><ul><li>Une topographie « <strong>rhizomélique</strong> », intéressant les ceintures scapulaire (épaules, rachis cervical) et pelvienne (bassin, cuisses, fesses, rachis lombaire bas).</li><li>Une latéralité <strong>bilatérale</strong> et le plus souvent <strong>symétrique</strong>.</li><li>Un horaire <strong>inflammatoire</strong> : un enraidissement matinal de plus de 60 minutes et des réveils nocturnes en deuxième partie de nuit.</li><li>Une évolution depuis <strong>plus d'un mois</strong>.</li></ul>"},{"i":"e791512134bf","n":195,"o":"195-10","u":"Diagnostic positif","t":"Connaître les signes cliniques de la PPR","q":"Quels sont les « drapeaux rouges » qui doivent faire douter du diagnostic de pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>Les « drapeaux rouges » qui doivent remettre en question le diagnostic de PPR sont :</p><ul><li>Des <strong>signes généraux intenses</strong>.</li><li>L'<strong>absence d'atteinte des épaules</strong>.</li><li>Une <strong>organomégalie</strong> (adénopathies, splénomégalie, hépatomégalie).</li><li>Une <strong>atteinte des petits vaisseaux</strong> (purpura, syndrome néphritique/néphrotique, mononeuropathie multiple, polynévrite).</li><li>L'<strong>absence de réponse</strong> après quelques jours de corticothérapie.</li><li>L'<strong>absence de syndrome inflammatoire biologique</strong> (SIB).</li></ul>"},{"i":"fd4a25550d58","n":195,"o":"195-10","u":"Diagnostic positif","t":"Connaître les signes cliniques de la PPR","q":"Quels sont les éléments retrouvés à l'examen clinique et les manifestations associées fréquents dans la pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>À l'examen clinique de la PPR, on retrouve :</p><ul><li>Une <strong>impotence fonctionnelle</strong> et une <strong>raideur</strong>.</li><li>Des <strong>douleurs à la palpation</strong> des masses musculaires.</li><li>Des <strong>douleurs à la mobilisation articulaire</strong> (glenohumérales, coxofémorales, rachis cervical et lombaire).</li></ul><p>Les manifestations associées incluent :</p><ul><li>Une <strong>asthénie</strong> (90%), une anorexie, un amaigrissement, et parfois un fébricule (AEG moins intense que dans l'ACG).</li><li>Plus rarement (20%), des arthralgies, arthrites ou ténosynovites périphériques (mains, poignets).</li></ul>"},{"i":"6918fea3568c","n":195,"o":"195-2","u":"Définition","t":"Connaître la définition de la pseudo-polyarthrite rhizomélique (PPR)","q":"Quel est le lien entre la pseudo-polyarthrite rhizomélique (PPR) et l'artérite à cellules géantes (ACG) ?","a":"<p>La pseudo-polyarthrite rhizomélique (PPR) <strong>n'est pas une vascularite</strong> et n'entraîne pas d'atteinte d'appareil autre que locomoteur. Il existe néanmoins un lien important avec l'artérite à cellules géantes (ACG) :</p><ul><li><strong>40 à 60 %</strong> des patients atteints d'ACG présentent des symptômes de PPR.</li><li><strong>20 %</strong> des patients atteints de PPR ont une ACG associée.</li><li>Toute PPR doit faire rechercher cliniquement une ACG associée.</li></ul>"},{"i":"7c50763ffbf2","n":195,"o":"195-2","u":"Définition","t":"Connaître la définition de la pseudo-polyarthrite rhizomélique (PPR)","q":"Quelles sont les caractéristiques épidémiologiques de la pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>La pseudo-polyarthrite rhizomélique (PPR) touche typiquement les sujets de <strong>plus de 50 ans</strong>, avec une nette <strong>prédominance féminine</strong> (2 femmes pour 1 homme) et un pic d'incidence entre <strong>70 et 80 ans</strong>.</p>"},{"i":"81db4565a9b5","n":195,"o":"195-2","u":"Définition","t":"Connaître la définition de la pseudo-polyarthrite rhizomélique (PPR)","q":"Quelle est la définition de la pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>La pseudo-polyarthrite rhizomélique (PPR) est un <strong>rhumatisme inflammatoire bilatéral et symétrique</strong> touchant les <strong>ceintures scapulaire et pelvienne</strong>. Elle se caractérise par des <strong>arthro-myalgies à horaire inflammatoire</strong> (notamment une raideur matinale > 60 min) évoluant depuis <strong>plus d'un mois</strong>.</p>"},{"i":"36aba2dfee01","n":195,"o":"195-4","u":"Diagnostic positif","t":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","q":"Quels sont les signes cliniques céphaliques fréquemment observés dans l'artérite à cellules géantes (ACG) ?","a":"<ul><li><strong>Céphalée temporale</strong> : unilatérale ou bilatérale, récente, d'intensité variable, et résistante au paracétamol.</li><li><strong>Hyperesthésie du cuir chevelu</strong> : douleur au coiffage (signe du peigne), avec un risque rare de nécrose du scalp.</li><li><strong>Claudication intermittente de la langue ou de la mâchoire</strong> : contracture des masséters à la mastication, régressive à l'arrêt, avec un risque rare de nécroses linguales.</li><li>À la palpation des artères temporales : <strong>induration, sensibilité, saillie, abolition ou diminution du pouls temporal</strong> (à rechercher des deux côtés, en avant du tragus).</li></ul>"},{"i":"4c547b1fd658","n":195,"o":"195-4","u":"Diagnostic positif","t":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","q":"Quels sont les signes généraux fréquemment observés dans l'artérite à cellules géantes (ACG) ?","a":"<p>Les signes généraux de l'artérite à cellules géantes (ACG) comprennent :</p><ul><li><strong>Fièvre</strong> : dépassant rarement 39 °C.</li><li><strong>Asthénie</strong> : fréquente.</li><li><strong>Anorexie et amaigrissement</strong> : une altération de l'état général (AEG) habituellement plus marquée que dans une pseudo-polyarthrite rhizomélique (PPR) isolée.</li></ul>"},{"i":"72eabb3e3e96","n":195,"o":"195-4","u":"Diagnostic positif","t":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","q":"Quels signes cliniques doivent faire remettre en question le diagnostic d'artérite à cellules géantes (ACG) ou de pseudo-polyarthrite rhizomélique (PPR) ?","a":"<p>Les signes qui doivent faire remettre en question le diagnostic d'ACG/PPR sont :</p><ul><li><strong>Organomégalie</strong> : adénopathies, splénomégalie, hépatomégalie.</li><li><strong>Atteinte des petits vaisseaux</strong> : purpura vasculaire, syndrome néphritique/néphrotique, mononeuropathie multiple, polynévrite (évoquant une vascularite à ANCA par exemple).</li><li><strong>Absence de réponse clinique</strong> après quelques jours de corticothérapie.</li><li><strong>Absence de syndrome inflammatoire biologique</strong>.</li></ul>"},{"i":"a978157d096e","n":195,"o":"195-4","u":"Diagnostic positif","t":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","q":"Quelle triade clinique doit faire suspecter une artérite à cellules géantes (ACG) selon les recommandations de l'EDN ?","a":"<p>La triade évocatrice d'une artérite à cellules géantes (ACG) est :</p><ul><li>Âge <strong>supérieur à 50 ans</strong></li><li><strong>Symptômes évocateurs</strong> (céphalées temporales, claudication de la mâchoire, troubles visuels, etc.)</li><li><strong>Syndrome inflammatoire biologique</strong> (par exemple, augmentation de la VS et de la CRP)</li></ul>"},{"i":"efa8873d65eb","n":195,"o":"195-4","u":"Diagnostic positif","t":"Connaître les signes cliniques fréquemment observés au cours de l’ACG","q":"Quels signes cliniques ophtalmologiques sont observés dans l'artérite à cellules géantes (ACG) ?","a":"<p>Les signes ophtalmologiques, retrouvés chez environ <strong>30%</strong> des patients ACG, incluent :</p><ul><li><strong>Baisse d'acuité visuelle unilatérale</strong> : indolore et brutale (observée chez 15% des patients).</li><li><strong>Amaurose brutale</strong> : perte de vision transitoire de quelques secondes à minutes.</li><li>Autres possibles : <strong>flou visuel, scotome</strong> ou <strong>diplopie transitoire</strong> (paralysie oculomotrice).</li></ul>"},{"i":"4c9d4b158179","n":195,"o":"195-6","u":"Identifier une urgence","t":"Connaître les complications ophtalmologiques de l’ACG : amaurose brutale, paralysie oculomotrice","q":"Quels sont les signes d'alerte cliniques d'une complication ophtalmologique de l'artérite à cellules géantes (ACG) ?","a":"<ul><li><strong>Baisse d'acuité visuelle (BAV) unilatérale</strong> : indolore, brutale, présente chez environ 15% des patients.</li><li><strong>Amaurose brutale</strong> : perte de vision transitoire, complète ou avec amputation du champ visuel, durant de quelques secondes à minutes.</li><li><strong>Flou visuel</strong>, <strong>scotome</strong>.</li><li><strong>Diplopie transitoire</strong> par paralysie oculomotrice (atteinte des nerfs oculomoteurs, concernant environ 2% des patients).</li></ul>"},{"i":"8ddc881eb54f","n":195,"o":"195-6","u":"Identifier une urgence","t":"Connaître les complications ophtalmologiques de l’ACG : amaurose brutale, paralysie oculomotrice","q":"Quelle est la principale complication ophtalmologique de l'artérite à cellules géantes (ACG) et quel est son mécanisme physiopathologique ?","a":"<p>La principale complication ophtalmologique de l'ACG est la <strong>neuropathie optique ischémique antérieure aiguë (NOIAA)</strong>, résultant d'une <strong>nécrose</strong> des structures optiques par ischémie.</p>"},{"i":"a72c8655f9d6","n":195,"o":"195-6","u":"Identifier une urgence","t":"Connaître les complications ophtalmologiques de l’ACG : amaurose brutale, paralysie oculomotrice","q":"Quelle est la conduite à tenir en urgence face à un patient suspect d'artérite à cellules géantes (ACG) présentant un signe ophtalmologique ?","a":"<p>Tout signe ophtalmologique chez un patient suspect d'ACG impose une <strong>corticothérapie en urgence</strong> (urgence thérapeutique absolue) pour prévenir la cécité bilatérale définitive.</p>"},{"i":"1504d47f8bdb","n":195,"o":"195-7","u":"Examens complémentaires","t":"Connaître les signes biologiques fréquents au cours de l’ACG","q":"Quelles anomalies de l'hémogramme peuvent être observées chez un patient atteint d'artérite à cellules géantes (ACG) ?","a":"<ul><li>Une possible <strong>anémie inflammatoire</strong>.</li><li>Une <strong>thrombocytose d'origine inflammatoire</strong>.</li></ul>"},{"i":"53606b548b23","n":195,"o":"195-7","u":"Examens complémentaires","t":"Connaître les signes biologiques fréquents au cours de l’ACG","q":"Quels sont les marqueurs biologiques du syndrome inflammatoire fréquemment observés lors d'une artérite à cellules géantes (ACG) ?","a":"<ul><li>Une élévation de la <strong>C-réactive protéine (CRP)</strong> et du <strong>fibrinogène</strong>, ou une élévation de la <strong>vitesse de sédimentation (VS)</strong> et de la CRP.</li><li>L'intensité est souvent très marquée, avec une CRP souvent <strong>supérieure à 40 mg/L</strong>, voire une VS <strong>supérieure à 40 mm/h</strong>.</li><li>L'absence de syndrome inflammatoire biologique rend le diagnostic d'ACG <strong>très improbable (&gt; 95 % de sensibilité)</strong>.</li></ul>"},{"i":"b3f3029798ff","n":195,"o":"195-7","u":"Examens complémentaires","t":"Connaître les signes biologiques fréquents au cours de l’ACG","q":"Quel est l'intérêt du bilan biologique dans le diagnostic de l'artérite à cellules géantes (ACG) ?","a":"<p>Le bilan biologique est principalement utilisé pour objectiver un <strong>syndrome inflammatoire biologique (SIB)</strong> et pour éliminer d'autres diagnostics, notamment des vascularites des petits vaisseaux.</p>"},{"i":"ff8d6b189b5a","n":195,"o":"195-7","u":"Examens complémentaires","t":"Connaître les signes biologiques fréquents au cours de l’ACG","q":"Existe-t-il des auto-anticorps spécifiques permettant de diagnostiquer l'artérite à cellules géantes (ACG) ?","a":"<p>Non, il n'existe <strong>aucun auto-anticorps spécifique</strong> de l'artérite à cellules géantes ou de la pseudopolyarthrite rhizomélique. La présence d'auto-anticorps (Facteur Rhumatoïde, Anticorps Anti-Nucléaires) est une <strong>coïncidence liée à l'âge</strong> et a peu d'importance diagnostique.</p>"},{"i":"09e03e93a6a1","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Quels sont les différents schémas de corticothérapie à l'instauration du traitement pour une artérite à cellules géantes (ACG) ?","a":"<ul><li><strong>Polyarthrite Rhumatoïde (PPR) isolée :</strong> prednisolone <strong>0,3 mg/kg/jour</strong> per os.</li><li><strong>ACG sans signe ischémique :</strong> prednisolone <strong>0,7 mg/kg/jour</strong> per os.</li><li><strong>ACG avec signes ophtalmiques ou ischémiques :</strong> <ul><li><strong>prednisolone 1 mg/kg/jour</strong> per os d'emblée, et y associer de l'<strong>aspirine antiagrégante</strong>.</li><li>OU <strong>bolus IV de méthylprednisolone</strong> pendant 1 à 3 jours, suivi d'un relais per os (efficacité non formellement prouvée).</li></ul></li></ul>"},{"i":"0e0cb26d5c14","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Comment évalue-t-on l'efficacité du traitement corticoïde dans l'artérite à cellules géantes (ACG) et quel est son intérêt diagnostique ?","a":"<p>L'efficacité est souvent <strong>spectaculaire</strong> :</p><ul><li><strong>Régression clinique</strong> en <strong>24 à 72 heures</strong>.</li><li><strong>Normalisation du syndrome inflammatoire biologique (SIB)</strong> : quelques jours pour la CRP, <strong>3 semaines</strong> pour la VS.</li></ul><p>Le cortico-test a un <strong>intérêt diagnostique</strong> : une absence de corticosensibilité remet en question le diagnostic d'ACG.</p>"},{"i":"182b293adb06","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Quels sont les risques et les alternatives thérapeutiques pour la prise en charge de l'artérite à cellules géantes (ACG) ?","a":"<ul><li><strong>Risques :</strong> Les traitements prolongés exposent aux risques liés aux corticoïdes : ostéoporose, cataracte, diabète, notamment.</li><li><strong>Alternatives (épargne cortisonique) :</strong> <ul><li><strong>Méthotrexate</strong> (hors AMM).</li><li><strong>Tocilizumab</strong> (anti-IL-6), dont la prescription est réservée aux spécialistes.</li></ul></li></ul>"},{"i":"18597b18d20c","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Quel est le pronostic global de l'artérite à cellules géantes (ACG) et quelles sont ses principales complications ?","a":"<p>Le pronostic est globalement <strong>bon</strong>, la survie globale est comparable à celle de la population générale (pas de surmortalité démontrée).</p><p>Les principales complications sont :</p><ul><li><strong>Cécité totale :</strong> survient dans <strong>1 à 2 % des cas</strong> d'ACG.</li><li><strong>Rechutes :</strong> possibles, parfois tardives (jusqu'à 10 ans après le diagnostic). En cas de rechute à dose élevée ou avec persistance d'altération de l'état général (AEG), une néoplasie doit être discutée.</li></ul>"},{"i":"6ca904126ca4","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Quels sont les principes et la durée de la décroissance de la corticothérapie dans l'artérite à cellules géantes (ACG) ?","a":"<ul><li><strong>Quand ?</strong> La décroissance débute après la disparition des signes cliniques et la régression du SIB.</li><li><strong>Comment ?</strong> Diminution progressive par paliers toutes les <strong>2 à 4 semaines</strong> (ex : jusqu'à 30 mg/j → -10 mg ; jusqu'à 10 mg/j → -5 à 2,5 mg ou -10% ; au-delà → -1 mg).</li><li><strong>Durée ?</strong> Le sevrage est visé autour de <strong>18 mois</strong> (entre 12 et 24 mois).</li></ul>"},{"i":"945747322618","n":195,"o":"195-9","u":"Prise en charge","t":"Connaître les principes du traitement de l’ACG et son pronostic","q":"Quelle est l'attitude thérapeutique initiale face à une suspicion forte d'artérite à cellules géantes (ACG), notamment en présence de signes ischémiques ?","a":"<p>L'ACG est une <strong>urgence thérapeutique</strong>, surtout en présence de signes ischémiques (ophtalmiques, accidents vasculaires cérébraux, ischémie de membre). Il faut débuter une <strong>corticothérapie sans délai</strong>, sans attendre le résultat de la biopsie de l'artère temporale (BAT).</p>"}]};